import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = opp[-1]
    last_my = my[-1]

    # Count consecutive defections by opponent at the end
    tail_def = 0
    for a in reversed(opp):
        if a == 'D':
            tail_def += 1
        else:
            break

    # Count consecutive cooperations by opponent at the end
    tail_coop = 0
    for a in reversed(opp):
        if a == 'C':
            tail_coop += 1
        else:
            break

    opp_coop = sum(1 for a in opp if a == 'C')
    opp_coop_rate = opp_coop / n

    recent_len = min(10, n)
    recent = opp[-recent_len:]
    recent_coop = sum(1 for a in recent if a == 'C')
    recent_rate = recent_coop / recent_len

    remaining = 100 - n

    # Against a purely/almost purely cooperative opponent, mildly exploit late.
    if opp_coop_rate > 0.9 and tail_def == 0:
        if remaining <= 1:
            return 'D'
        # rare probe
        if n >= 20 and n % 9 == 0:
            return 'D'
        return 'C'

    # Strong retaliator: defect back on defections, but with controlled forgiveness.
    if last_opp == 'D':
        # Long defect streak: keep defecting
        if tail_def >= 3:
            return 'D'
        # Opponent is generally cooperative: forgive quickly to restore CC
        if opp_coop_rate > 0.6:
            # Forgive single isolated defection
            if tail_def == 1 and tail_coop >= 2:
                return 'C'
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        # Opponent is mostly defective: defect
        if opp_coop_rate < 0.4:
            return 'D'
        # Mixed opponent: mostly retaliate, sometimes forgive
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if opp_coop_rate < 0.3:
        # Opponent rarely cooperates; punish/defect mostly
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    if opp_coop_rate < 0.55:
        # Moderately defective: cautiously cooperate
        if recent_rate < 0.4:
            return 'D'
        return 'C'

    # Opponent is mostly cooperative.
    # If we defected last and they still cooperated, exploit a bit but don't overdo.
    if last_my == 'D':
        if remaining > 5 and rng.random() < 0.35:
            return 'D'
        return 'C'

    # Mutually cooperating: maintain CC, with slight probing and endgame.
    if remaining <= 1:
        return 'D'
    if remaining <= 3 and opp_coop_rate > 0.7 and rng.random() < 0.35:
        return 'D'
    # Very occasional probe against a very cooperative opponent
    if opp_coop_rate > 0.85 and n >= 15 and n % 12 == 0:
        return 'D'

    return 'C'
